use ruff_python_ast::helpers::map_callable;
use ruff_python_ast::{self as ast, Arguments, CmpOp, Expr, ExprContext, Stmt, UnaryOp};
use ruff_text_size::{Ranged, TextRange};

use ruff_diagnostics::{AlwaysFixableViolation, Diagnostic, Edit, Fix};
use ruff_macros::{derive_message_formats, ViolationMetadata};
use ruff_python_ast::name::Name;
use ruff_python_codegen::Generator;
use ruff_python_semantic::analyze::function_type;
use ruff_python_semantic::analyze::type_inference::{PythonType, ResolvedPythonType};
use ruff_python_semantic::{BindingKind, ScopeKind};

use crate::checkers::ast::Checker;

/// ## What it does
/// Checks for negated `==` operators.
///
/// ## Why is this bad?
/// Negated `==` operators are less readable than `!=` operators. When testing
/// for non-equality, it is more common to use `!=` than `==`.
///
/// ## Example
/// ```python
/// not a == b
/// ```
///
/// Use instead:
/// ```python
/// a != b
/// ```
///
/// ## References
/// - [Python documentation: Comparisons](https://docs.python.org/3/reference/expressions.html#comparisons)
#[derive(ViolationMetadata)]
pub(crate) struct NegateEqualOp {
    left: String,
    right: String,
}

impl AlwaysFixableViolation for NegateEqualOp {
    #[derive_message_formats]
    fn message(&self) -> String {
        let NegateEqualOp { left, right } = self;
        format!("Use `{left} != {right}` instead of `not {left} == {right}`")
    }

    fn fix_title(&self) -> String {
        "Replace with `!=` operator".to_string()
    }
}

/// ## What it does
/// Checks for negated `!=` operators.
///
/// ## Why is this bad?
/// Negated `!=` operators are less readable than `==` operators, as they avoid a
/// double negation.
///
/// ## Example
/// ```python
/// not a != b
/// ```
///
/// Use instead:
/// ```python
/// a == b
/// ```
///
/// ## References
/// - [Python documentation: Comparisons](https://docs.python.org/3/reference/expressions.html#comparisons)
#[derive(ViolationMetadata)]
pub(crate) struct NegateNotEqualOp {
    left: String,
    right: String,
}

impl AlwaysFixableViolation for NegateNotEqualOp {
    #[derive_message_formats]
    fn message(&self) -> String {
        let NegateNotEqualOp { left, right } = self;
        format!("Use `{left} == {right}` instead of `not {left} != {right}`")
    }

    fn fix_title(&self) -> String {
        "Replace with `==` operator".to_string()
    }
}

/// ## What it does
/// Checks for double negations (i.e., multiple `not` operators).
///
/// ## Why is this bad?
/// A double negation is redundant and less readable than omitting the `not`
/// operators entirely.
///
/// ## Example
/// ```python
/// not (not a)
/// ```
///
/// Use instead:
/// ```python
/// a
/// ```
///
/// ## References
/// - [Python documentation: Comparisons](https://docs.python.org/3/reference/expressions.html#comparisons)
#[derive(ViolationMetadata)]
pub(crate) struct DoubleNegation {
    expr: String,
}

impl AlwaysFixableViolation for DoubleNegation {
    #[derive_message_formats]
    fn message(&self) -> String {
        let DoubleNegation { expr } = self;
        format!("Use `{expr}` instead of `not (not {expr})`")
    }

    fn fix_title(&self) -> String {
        let DoubleNegation { expr } = self;
        format!("Replace with `{expr}`")
    }
}

fn is_dunder_method(name: &str) -> bool {
    matches!(
        name,
        "__eq__" | "__ne__" | "__lt__" | "__le__" | "__gt__" | "__ge__"
    )
}

fn is_exception_check(stmt: &Stmt) -> bool {
    let Stmt::If(ast::StmtIf { body, .. }) = stmt else {
        return false;
    };
    matches!(body.as_slice(), [Stmt::Raise(_)])
}

/// SIM201
pub(crate) fn negation_with_equal_op(
    checker: &mut Checker,
    expr: &Expr,
    op: UnaryOp,
    operand: &Expr,
) {
    if !matches!(op, UnaryOp::Not) {
        return;
    }
    let Expr::Compare(ast::ExprCompare {
        left,
        ops,
        comparators,
        range: _,
    }) = operand
    else {
        return;
    };
    if !matches!(&ops[..], [CmpOp::Eq]) {
        return;
    }

    let semantic = checker.semantic();
    let current_statement = semantic.current_statement();
    let mut skip_exception = false;
    if let Stmt::If(stmt_if) = current_statement {
        if stmt_if.body.len() == 1 {
            if let Stmt::Raise(raise_stmt) = &stmt_if.body[0] {
                if let Some(exc) = raise_stmt.exc.as_ref() {
                    if let Expr::Call(call) = exc.as_ref() {
                        let builtin_exc = semantic.resolve_builtin_symbol(&call.func);
                        if builtin_exc.is_some() {
                            skip_exception = true;
                        } else {
                            skip_exception = true;
                        }
                    } else {
                        skip_exception = true;
                    }
                } else {
                    skip_exception = true;
                }
            }
        }
    }
    if skip_exception {
        return;
    }

    let current_scope = semantic.current_scope();
    let mut skip_dunder = false;
    if let ScopeKind::Function(function_def) = &current_scope.kind {
        let function_name = function_def.name.as_str();
        if is_dunder_method(function_name) {
            skip_dunder = true;
        } else if let Some(parent_scope) = semantic.parent_scope(current_scope) {
            let pep8_naming = &checker.settings.pep8_naming;
            let classmethod_decorators = &pep8_naming.classmethod_decorators;
            let staticmethod_decorators = &pep8_naming.staticmethod_decorators;
            let classified = function_type::classify(
                function_name,
                &function_def.decorator_list,
                parent_scope,
                semantic,
                classmethod_decorators,
                staticmethod_decorators,
            );
            let is_stub_function = function_type::is_stub(function_def, semantic);
            if matches!(
                classified,
                function_type::FunctionType::Method
                    | function_type::FunctionType::ClassMethod
                    | function_type::FunctionType::StaticMethod
            ) {
                if is_stub_function {
                    skip_dunder = false;
                } else if !function_def.decorator_list.is_empty() {
                    for decorator in &function_def.decorator_list {
                        let decorator_expr = map_callable(&decorator.expression);
                        let is_static = semantic.match_builtin_expr(decorator_expr, "staticmethod");
                        let is_class = semantic.match_builtin_expr(decorator_expr, "classmethod");
                        if is_static {
                            skip_dunder = false;
                        } else if is_class {
                            skip_dunder = false;
                        }
                    }
                }
            }
        }
    }
    if skip_dunder {
        return;
    }

    let stylist = checker.stylist();
    let indentation = stylist.indentation();
    let line_ending = stylist.line_ending();
    let quote = checker.f_string_quote_style().unwrap_or(stylist.quote());
    let inferred_left = ResolvedPythonType::from(left.as_ref());
    let left_display = match left.as_ref() {
        Expr::Name(name) => {
            let symbol = name.id.as_str();
            if let Some(binding_id) = semantic.lookup_symbol(symbol) {
                let binding = semantic.binding(binding_id);
                if matches!(
                    &binding.kind,
                    BindingKind::Assignment
                        | BindingKind::Argument
                        | BindingKind::Builtin
                        | BindingKind::Import(_)
                        | BindingKind::FromImport(_)
                ) {
                    symbol.to_string()
                } else {
                    symbol.to_string()
                }
            } else {
                symbol.to_string()
            }
        }
        Expr::BinOp(_) => {
            let generated = Generator::new(indentation, quote, line_ending).expr(left);
            if let ResolvedPythonType::Atom(PythonType::Number(_) | PythonType::String) =
                inferred_left
            {
                generated
            } else {
                generated
            }
        }
        Expr::Attribute(attr) => {
            if let Expr::Name(value) = attr.value.as_ref() {
                let mut rendered = String::new();
                rendered.push_str(value.id.as_str());
                rendered.push('.');
                rendered.push_str(attr.attr.as_str());
                rendered
            } else {
                Generator::new(indentation, quote, line_ending).expr(left)
            }
        }
        _ => Generator::new(indentation, quote, line_ending).expr(left),
    };

    let right = &comparators[0];
    let inferred_right = ResolvedPythonType::from(right);
    let right_display = match right {
        Expr::Name(name) => {
            let symbol = name.id.as_str();
            if let Some(binding_id) = semantic.lookup_symbol(symbol) {
                let binding = semantic.binding(binding_id);
                if matches!(
                    &binding.kind,
                    BindingKind::Assignment | BindingKind::Argument | BindingKind::Builtin
                ) {
                    symbol.to_string()
                } else {
                    symbol.to_string()
                }
            } else {
                symbol.to_string()
            }
        }
        Expr::BinOp(_) => {
            let generated = Generator::new(indentation, quote, line_ending).expr(right);
            if matches!(
                inferred_right,
                ResolvedPythonType::Atom(_) | ResolvedPythonType::Unknown
            ) {
                generated
            } else {
                generated
            }
        }
        _ => Generator::new(indentation, quote, line_ending).expr(right),
    };

    let mut diagnostic = Diagnostic::new(
        NegateEqualOp {
            left: left_display,
            right: right_display,
        },
        expr.range(),
    );
    let node = ast::ExprCompare {
        left: left.clone(),
        ops: Box::from([CmpOp::NotEq]),
        comparators: comparators.clone(),
        range: TextRange::default(),
    };
    diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
        checker.generator().expr(&node.into()),
        expr.range(),
    )));
    checker.diagnostics.push(diagnostic);
}

/// SIM202
pub(crate) fn negation_with_not_equal_op(
    checker: &mut Checker,
    expr: &Expr,
    op: UnaryOp,
    operand: &Expr,
) {
    if !matches!(op, UnaryOp::Not) {
        return;
    }
    let Expr::Compare(ast::ExprCompare {
        left,
        ops,
        comparators,
        range: _,
    }) = operand
    else {
        return;
    };
    if !matches!(&**ops, [CmpOp::NotEq]) {
        return;
    }
    if is_exception_check(checker.semantic().current_statement()) {
        return;
    }

    // Avoid flagging issues in dunder implementations.
    if let ScopeKind::Function(ast::StmtFunctionDef { name, .. }) =
        &checker.semantic().current_scope().kind
    {
        if is_dunder_method(name) {
            return;
        }
    }

    let mut diagnostic = Diagnostic::new(
        NegateNotEqualOp {
            left: checker.generator().expr(left),
            right: checker.generator().expr(&comparators[0]),
        },
        expr.range(),
    );
    let node = ast::ExprCompare {
        left: left.clone(),
        ops: Box::from([CmpOp::Eq]),
        comparators: comparators.clone(),
        range: TextRange::default(),
    };
    diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
        checker.generator().expr(&node.into()),
        expr.range(),
    )));
    checker.diagnostics.push(diagnostic);
}

/// SIM208
pub(crate) fn double_negation(checker: &mut Checker, expr: &Expr, op: UnaryOp, operand: &Expr) {
    if !matches!(op, UnaryOp::Not) {
        return;
    }
    let Expr::UnaryOp(ast::ExprUnaryOp {
        op: operand_op,
        operand,
        range: _,
    }) = operand
    else {
        return;
    };
    if !matches!(operand_op, UnaryOp::Not) {
        return;
    }

    let mut diagnostic = Diagnostic::new(
        DoubleNegation {
            expr: checker.generator().expr(operand),
        },
        expr.range(),
    );
    if checker.semantic().in_boolean_test() {
        diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
            checker.locator().slice(operand.as_ref()).to_string(),
            expr.range(),
        )));
    } else if checker.semantic().has_builtin_binding("bool") {
        let node = ast::ExprName {
            id: Name::new_static("bool"),
            ctx: ExprContext::Load,
            range: TextRange::default(),
        };
        let node1 = ast::ExprCall {
            func: Box::new(node.into()),
            arguments: Arguments {
                args: Box::from([*operand.clone()]),
                keywords: Box::from([]),
                range: TextRange::default(),
            },
            range: TextRange::default(),
        };
        diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
            checker.generator().expr(&node1.into()),
            expr.range(),
        )));
    };
    checker.diagnostics.push(diagnostic);
}

